llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, a retinoic acid analogue sharing the same polyene/cyclohexene retinoid scaffold, has a systemic bioavailability of 40% in patients, directly supporting F ≥ 20% for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "All-trans retinoic acid (tretinoin) is estimated to have approximately 50% oral bioavailability in humans, providing another close retinoid analogue with bioavailability well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Acitretin, an aromatic retinoid with very low aqueous solubility, has an absolute oral bioavailability of about 60% (range 36–95%) when given with food, showing that high lipophilicity and poor solubility do not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, a retinoid ester, has an absolute oral bioavailability of about 40% in healthy volunteers, further supporting that retinoid-like molecules with this scaffold can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Paracetamol, which shares the p-hydroxyanilide substructure with the query, has an absolute oral bioavailability of about 82%, indicating that the phenolic amide moiety is not inherently bioavailability-limiting, although its much smaller size limits transferability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a fenretinide-like retinoid amide. Multiple retinoid analogues with the same polyene/cyclohexene scaffold and similarly high lipophilicity have absolute oral bioavailability values of 40–60%, all above the 20% threshold. The shared p-hydroxyanilide motif with paracetamol also supports adequate absorption. Although very high logP and poor solubility are concerns, the retinoid evidence indicates these features can still be compatible with F ≥ 20%, especially with food-dependent absorption. Therefore, high bioavailability is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide itself in humans.",
    "No intravenous comparator data for the query molecule.",
    "Fed/fasted conditions and formulation effects for the query are not specified.",
    "First-pass glucuronidation of the phenolic group and its impact on systemic availability are not quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

